-- 00063_launch_plays.sql
--
-- Launch plays (phase F4 of docs/plans/film-and-plays.md, section 10): 26
-- more library plays, taking the library from the 10 starter plays in 00060
-- to 36. Principles, half-court sets, pick-and-roll, baseline and sideline
-- out of bounds, a press break, zone offences (U15 and up) and end of
-- quarter plays.
--
-- Data only: the plays table and its rules are in 00060 and 00061, which must
-- be run first. The rows are generated from src/data/plays/launch.ts by
-- __tests__/plays-library.test.ts; change a play there, never here.
--
-- Safe to re-run: a library play with the same slug is updated in place.
-- The 10 starter plays in 00060 are not touched.
--
-- NOTE ON STYLE: no apostrophes in the comments of this file, for the reason
-- given at the top of 00035. Keep it apostrophe-free.

-- BEGIN LIBRARY PLAYS (generated from src/data/plays/library.ts by __tests__/plays-library.test.ts; do not edit by hand)
ON CONFLICT (slug) WHERE owner_id IS NULL DO UPDATE SET
  title = EXCLUDED.title, category = EXCLUDED.category, min_age = EXCLUDED.min_age, tags = EXCLUDED.tags,
  description = EXCLUDED.description, coaching_points = EXCLUDED.coaching_points, diagram = EXCLUDED.diagram,
  is_free = EXCLUDED.is_free, updated_at = now();
-- END LIBRARY PLAYS
