INSERT INTO public.plays (slug, title, category, min_age, tags, description, coaching_points, diagram, is_free) VALUES
  ('dribble-drive', 'Dribble-drive: drive and kick', 'principles', 'U10', ARRAY['driving', 'spacing', 'kick-out']::text[], 'Drive into a gap, and everyone else moves to where the driver can see them. If a defender helps, pass to the player they left, who attacks again.', ARRAY['Drive hard into the gap between two defenders, with your head up.', 'If the drive comes toward you, move away to a spot where the driver can see you.', 'Someone always fills the spot behind the drive, so there is a pass back out.', 'Driver: if a defender helps, pass to the teammate they left. If nobody helps, finish at the basket.', 'Catch ready to shoot, drive or pass. Do not hold the ball.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":48.5,"y":3},"o5":{"x":1.5,"y":3}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":29,"y":13},"o2":{"x":45,"y":21},"o3":{"x":25,"y":31},"o4":{"x":48.5,"y":3},"o5":{"x":1.5,"y":3}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[{"x":28,"y":24}]},{"type":"cut","from":"o3","path":[]}],"note":"1 drives the gap; 3 fills the top behind the drive."},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":45,"y":21},"o3":{"x":25,"y":31},"o4":{"x":48.5,"y":3},"o5":{"x":1.5,"y":3}},"ball":"o2","actions":[{"type":"pass","from":"o1","to":"o2","path":[]},{"type":"cut","from":"o1","path":[{"x":20,"y":9}]}],"note":"2''s defender helped, so 1 passes out to 2, then clears to the open spot."},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":39.5,"y":6},"o3":{"x":25,"y":31},"o4":{"x":45,"y":21},"o5":{"x":1.5,"y":3}},"ball":"o2","actions":[{"type":"dribble","from":"o2","path":[{"x":44,"y":13}]},{"type":"cut","from":"o4","path":[]}],"note":"2 attacks the baseline; 4 lifts out of the corner to the wing."},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":39.5,"y":6},"o3":{"x":25,"y":31},"o4":{"x":45,"y":21},"o5":{"x":1.5,"y":3}},"ball":"o4","actions":[{"type":"pass","from":"o2","to":"o4","path":[]}],"note":"Pass out to 4 for the shot, or 2 finishes if nobody helps."}]}'::jsonb, true),
  ('spacing-fill-the-spots', 'Spacing: fill the open spot', 'principles', 'U9', ARRAY['spacing', 'cutting', 'motion']::text[], 'Good spacing gives the ball handler room. Here 1 dribbles toward 2, 2 cuts to the basket, and everyone moves so that each open spot is filled again.', ARRAY['Stand 12 to 15 feet from your nearest teammate, so one defender cannot guard two of you.', 'If a teammate dribbles at you, cut to the basket.', 'When a spot opens up, the nearest player fills it.', 'Stay out of the paint unless you are cutting through it.', 'Keep the corners filled: a player there pulls a defender away from the basket.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":48.5,"y":3},"o5":{"x":1.5,"y":3}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":26,"y":7},"o3":{"x":5,"y":21},"o4":{"x":48.5,"y":3},"o5":{"x":1.5,"y":3}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[]},{"type":"cut","from":"o2","path":[{"x":41,"y":14}]}],"note":"1 dribbles at 2, so 2 cuts to the basket."},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":48.5,"y":3},"o3":{"x":5,"y":21},"o4":{"x":45,"y":21},"o5":{"x":1.5,"y":3}},"ball":"o1","actions":[{"type":"cut","from":"o4","path":[]},{"type":"cut","from":"o2","path":[{"x":36,"y":5}]}],"note":"4 fills the wing 2 left; 2 clears to the corner 4 left."},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":48.5,"y":3},"o3":{"x":15.5,"y":28.5},"o4":{"x":45,"y":21},"o5":{"x":5,"y":21}},"ball":"o1","actions":[{"type":"cut","from":"o3","path":[]},{"type":"cut","from":"o5","path":[]}],"note":"The other side moves up one spot each, so no spot stays empty."},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":48.5,"y":3},"o3":{"x":15.5,"y":28.5},"o4":{"x":45,"y":21},"o5":{"x":5,"y":21}},"ball":"o3","actions":[{"type":"pass","from":"o1","to":"o3","path":[]}],"note":"Now the ball can swing to the other side."}]}'::jsonb, true),
  ('horns-flare', 'Horns: flare for the shooter', 'half_court', 'U11', ARRAY['horns', 'flare screen', 'shooter']::text[], 'A Horns set without a ball screen. 1 passes to 4, then fades away from the ball off a screen from 5 for an open shot on the wing.', ARRAY['Start in Horns: bigs at the elbows, shooters in the corners.', '4 pops out to catch. The pass to 4 starts the play.', '5 screens and holds still. 1 waits for the screen, then fades to the wing.', '1 catches with feet set, ready to shoot.', 'After the screen, 5 slips to the basket. If the defence helps on 1, 5 is open.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":17,"y":19},"o5":{"x":33,"y":19}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":33,"y":19}},"ball":"o1","actions":[{"type":"cut","from":"o4","path":[]}],"note":"4 pops out of the elbow to catch."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":33,"y":19}},"ball":"o4","actions":[{"type":"pass","from":"o1","to":"o4","path":[]}]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":29,"y":27}},"ball":"o4","actions":[{"type":"screen","from":"o5","to":"o1","path":[]}],"note":"5 steps up and screens for 1."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":29,"y":27}},"ball":"o4","actions":[{"type":"cut","from":"o1","path":[{"x":31.5,"y":30.5}]}],"note":"1 fades away from the ball, off the screen, to the wing."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":27,"y":8}},"ball":"o1","actions":[{"type":"pass","from":"o4","to":"o1","path":[]},{"type":"cut","from":"o5","path":[]}],"note":"Catch and shoot. 5 slips to the basket in case the defence helps."}]}'::jsonb, false),
  ('horns-down', 'Horns: down screens for the corners', 'half_court', 'U11', ARRAY['horns', 'down screen', 'post']::text[], 'From Horns, the two bigs go down and screen for the shooters in the corners. The shooters come up to the wings, and the bigs step in toward the ball.', ARRAY['Screeners: go down to the corner player, stop, and hold still.', 'Corner players: wait for the screen, then come up hard past the screener''s shoulder.', 'After screening, the big steps toward the ball. The screener is often the one left open.', '2 catches on the wing facing the basket: shoot, pass inside, or drive.', 'Feed the post with a bounce pass, away from the defender.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":17,"y":19},"o5":{"x":33,"y":19}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":5,"y":9},"o5":{"x":45,"y":9}},"ball":"o1","actions":[{"type":"screen","from":"o4","to":"o3","path":[]},{"type":"screen","from":"o5","to":"o2","path":[]}],"note":"4 and 5 go down and screen for the corners."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":5,"y":9},"o5":{"x":45,"y":9}},"ball":"o1","actions":[{"type":"cut","from":"o3","path":[{"x":3,"y":12}]},{"type":"cut","from":"o2","path":[{"x":47,"y":12}]}],"note":"3 and 2 come up off the screens to the wings."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":5,"y":9},"o5":{"x":45,"y":9}},"ball":"o2","actions":[{"type":"pass","from":"o1","to":"o2","path":[]}]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":25,"y":20},"o5":{"x":34.5,"y":8}},"ball":"o2","actions":[{"type":"cut","from":"o5","path":[]},{"type":"cut","from":"o4","path":[]}],"note":"5 steps in to the ball-side block; 4 flashes to the high post."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":25,"y":20},"o5":{"x":34.5,"y":8}},"ball":"o5","actions":[{"type":"pass","from":"o2","to":"o5","path":[]}],"note":"Pass inside to 5, or to 4 at the high post."}]}'::jsonb, false),
  ('spain-pick-and-roll', 'Spain pick-and-roll', 'half_court', 'U15', ARRAY['spain', 'ball screen', 'back screen']::text[], 'A pick-and-roll with a twist: as 5 rolls to the basket, 2 sets a back screen on 5''s defender, then pops out for a shot. Two good passes for 1 to choose from.', ARRAY['Learn the basic pick-and-roll first. Spain adds a back screen to free the roller.', '2 waits at the free throw line, then screens 5''s defender as 5 rolls.', '5 rolls hard to the basket with a hand up.', 'After screening, 2 pops out to the three-point line. The defence often loses 2.', '1 reads it: pass to 5 rolling, to 2 popping, or shoot.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":25,"y":20},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":33,"y":19}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":25,"y":20},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":28,"y":28.5}},"ball":"o1","actions":[{"type":"screen","from":"o5","to":"o1","path":[]}],"note":"5 screens for 1."},{"ms":1000,"positions":{"o1":{"x":37,"y":22},"o2":{"x":28,"y":23.5},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":28,"y":28.5}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[{"x":31.5,"y":30.5}]},{"type":"screen","from":"o2","to":"o5","path":[]}],"note":"1 comes off the screen; 2 steps up to screen 5''s defender."},{"ms":1000,"positions":{"o1":{"x":37,"y":22},"o2":{"x":28,"y":23.5},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":27,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[{"x":30.5,"y":22}]}],"note":"5 rolls to the basket past 2''s screen."},{"ms":1000,"positions":{"o1":{"x":37,"y":22},"o2":{"x":25,"y":31},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":27,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o2","path":[]}],"note":"2 pops out to the top for a shot."},{"ms":1000,"positions":{"o1":{"x":37,"y":22},"o2":{"x":25,"y":31},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":27,"y":8}},"ball":"o5","actions":[{"type":"pass","from":"o1","to":"o5","path":[]}],"note":"Pass to 5 rolling, or to 2 at the top if the defence covers 5."}]}'::jsonb, false),
  ('chin', 'Chin: back screen, then ball screen', 'half_court', 'U13', ARRAY['chin', 'back screen', 'ball screen']::text[], 'Two screens from the same player. 4 back screens for 1 to cut to the basket, then goes out and sets a ball screen for 2 on the wing.', ARRAY['The first pass to the wing starts Chin.', '4 back screens for 1, who cuts hard to the basket. Look for 1 first.', '1 is not open? Keep going to the ball-side corner.', '4 then screens for 2. 2 waits for it, then goes over the top toward the middle.', '4 rolls to the basket. 2 passes to 4, to 1 in the corner, or shoots.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":33,"y":19},"o5":{"x":15.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":33,"y":19},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"pass","from":"o1","to":"o2","path":[]}],"note":"Pass to the wing."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":28,"y":25.5},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"screen","from":"o4","to":"o1","path":[]}],"note":"4 steps up to back screen for 1."},{"ms":1000,"positions":{"o1":{"x":26,"y":8},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":28,"y":25.5},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"cut","from":"o1","path":[{"x":30,"y":23}]}],"note":"1 cuts off 4 to the basket. Pass if 1 is open."},{"ms":1000,"positions":{"o1":{"x":48.5,"y":3},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":42,"y":23.5},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"cut","from":"o1","path":[{"x":38,"y":5}]},{"type":"screen","from":"o4","to":"o2","path":[]}],"note":"1 clears to the corner. 4 goes out to screen for 2."},{"ms":1000,"positions":{"o1":{"x":48.5,"y":3},"o2":{"x":32,"y":19},"o3":{"x":1.5,"y":3},"o4":{"x":42,"y":23.5},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"dribble","from":"o2","path":[{"x":41,"y":26.5}]}],"note":"2 goes over the screen toward the middle."},{"ms":1000,"positions":{"o1":{"x":48.5,"y":3},"o2":{"x":32,"y":19},"o3":{"x":1.5,"y":3},"o4":{"x":28,"y":8},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"cut","from":"o4","path":[]}],"note":"4 rolls to the basket."},{"ms":1000,"positions":{"o1":{"x":48.5,"y":3},"o2":{"x":32,"y":19},"o3":{"x":1.5,"y":3},"o4":{"x":28,"y":8},"o5":{"x":15.5,"y":8}},"ball":"o4","actions":[{"type":"pass","from":"o2","to":"o4","path":[]}],"note":"Pass to 4 rolling, or to 1 in the corner."}]}'::jsonb, false),
  ('ucla-cut', 'UCLA cut', 'half_court', 'U10', ARRAY['ucla', 'back screen', 'cutting']::text[], 'The guard passes to the wing and cuts to the basket off a screen at the high post. Named after the UCLA college teams that made it famous.', ARRAY['Pass to the wing, then cut off the screen to the basket.', 'Walk your defender away first, then cut close to the screener''s shoulder.', '5: set the screen with your back to the basket and hold still.', 'Not open? 1 posts up on the block, and 5 pops out to the top.', 'Then swing the ball to the other side.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":25,"y":20}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":25,"y":20}},"ball":"o2","actions":[{"type":"pass","from":"o1","to":"o2","path":[]}]},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":31.5,"y":22.5}},"ball":"o2","actions":[{"type":"screen","from":"o5","to":"o1","path":[]}],"note":"5 steps out to screen for 1."},{"ms":1000,"positions":{"o1":{"x":27,"y":7.5},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":15.5,"y":8},"o5":{"x":31.5,"y":22.5}},"ball":"o2","actions":[{"type":"cut","from":"o1","path":[{"x":31,"y":19}]},{"type":"cut","from":"o3","path":[]}],"note":"1 cuts off 5 to the basket; 3 lifts to the wing."},{"ms":1000,"positions":{"o1":{"x":34.5,"y":8},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":15.5,"y":8},"o5":{"x":25,"y":31}},"ball":"o2","actions":[{"type":"cut","from":"o1","path":[]},{"type":"cut","from":"o5","path":[]}],"note":"1 posts up on the block; 5 pops out to the top."},{"ms":1000,"positions":{"o1":{"x":34.5,"y":8},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":15.5,"y":8},"o5":{"x":25,"y":31}},"ball":"o5","actions":[{"type":"pass","from":"o2","to":"o5","path":[]}]},{"ms":1000,"positions":{"o1":{"x":34.5,"y":8},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":15.5,"y":8},"o5":{"x":25,"y":31}},"ball":"o3","actions":[{"type":"pass","from":"o5","to":"o3","path":[]}],"note":"Swing the ball to the other side."}]}'::jsonb, true),
  ('flex', 'Flex: flex cut, then down screen', 'half_court', 'U11', ARRAY['flex', 'continuity', 'down screen']::text[], 'A pattern that keeps going: swing the ball, a baseline cut off a screen, then a down screen for the screener. The same moves repeat on the other side.', ARRAY['Every pass from one side to the other starts the next flex cut.', 'Cutter: walk your defender up, then cut close to the screener, along the baseline.', 'Screen the screener: after the flex cut, the passer goes down and screens for 5.', '5 comes up ready to catch and shoot.', 'Repeat it on the other side. The same moves keep going round.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":5,"y":21},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":5,"y":21},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":34.5,"y":8}},"ball":"o4","actions":[{"type":"pass","from":"o1","to":"o4","path":[]}],"note":"Swing the ball to start."},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":5,"y":21},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":37.5,"y":6}},"ball":"o4","actions":[{"type":"screen","from":"o5","to":"o3","path":[]}],"note":"5 screens for 3 in the corner."},{"ms":1000,"positions":{"o1":{"x":35,"y":13},"o2":{"x":5,"y":21},"o3":{"x":15.5,"y":8},"o4":{"x":15.5,"y":28.5},"o5":{"x":37.5,"y":6}},"ball":"o4","actions":[{"type":"cut","from":"o3","path":[{"x":36,"y":3.5},{"x":26,"y":5}]},{"type":"screen","from":"o1","to":"o5","path":[]}],"note":"3 cuts along the baseline to the ball side. 1 goes down to screen for 5."},{"ms":1000,"positions":{"o1":{"x":35,"y":13},"o2":{"x":5,"y":21},"o3":{"x":15.5,"y":8},"o4":{"x":15.5,"y":28.5},"o5":{"x":34.5,"y":28.5}},"ball":"o4","actions":[{"type":"cut","from":"o5","path":[{"x":36,"y":18}]}],"note":"5 comes up off the screen. If 3 is open on the block, 4 passes for the layup."},{"ms":1000,"positions":{"o1":{"x":48.5,"y":3},"o2":{"x":5,"y":21},"o3":{"x":15.5,"y":8},"o4":{"x":15.5,"y":28.5},"o5":{"x":34.5,"y":28.5}},"ball":"o5","actions":[{"type":"pass","from":"o4","to":"o5","path":[]},{"type":"cut","from":"o1","path":[]}],"note":"4 swings it back to 5. 1 steps out to the corner, ready for the next flex cut."}]}'::jsonb, false),
  ('stack', 'Stack: pop out, then cross screen', 'half_court', 'U10', ARRAY['stack', 'cross screen', 'post']::text[], 'Two stacks of two on the blocks. The top players pop out to the wings, then a screen across the lane frees 5 on the ball-side block.', ARRAY['Two players line up on each block. The players on top pop out to the wings.', 'Pop out hard and show your hands: you are the first pass.', '4 screens across the lane for 5, then steps up to the high post.', '5 waits for the screen, then cuts under it to the ball-side block.', 'Feed 5 with a bounce pass, or pass to 4 at the high post.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":14.5,"y":13},"o3":{"x":35.5,"y":13},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":5,"y":21},"o3":{"x":45,"y":21},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o2","path":[]},{"type":"cut","from":"o3","path":[]}],"note":"2 and 3 pop out of the stacks to the wings."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":5,"y":21},"o3":{"x":45,"y":21},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o2","actions":[{"type":"pass","from":"o1","to":"o2","path":[]}]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":5,"y":21},"o3":{"x":45,"y":21},"o4":{"x":29,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o2","actions":[{"type":"screen","from":"o4","to":"o5","path":[]}],"note":"4 screens across the lane for 5."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":5,"y":21},"o3":{"x":45,"y":21},"o4":{"x":29,"y":8},"o5":{"x":15.5,"y":8}},"ball":"o2","actions":[{"type":"cut","from":"o5","path":[{"x":28,"y":5}]}],"note":"5 cuts under the screen to the ball-side block."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":5,"y":21},"o3":{"x":45,"y":21},"o4":{"x":25,"y":20},"o5":{"x":15.5,"y":8}},"ball":"o5","actions":[{"type":"pass","from":"o2","to":"o5","path":[]},{"type":"cut","from":"o4","path":[]}],"note":"Pass inside to 5. 4 steps up to the high post."}]}'::jsonb, true),
  ('side-pick-and-roll', 'Side pick-and-roll', 'pick_and_roll', 'U12', ARRAY['ball screen', 'wing', 'two-player']::text[], 'A pick-and-roll from the wing. 5 screens on the top side so 1 can attack the middle, then rolls to the basket.', ARRAY['Screen on the top side of 1''s defender, so 1 can go toward the middle.', '1: wait for the screen, then go past it shoulder to shoulder.', '5 rolls to the basket as soon as 1 is past.', '2 stays in the corner: if their defender helps, 2 is open.', '3 lifts to the top so 1 always has a pass back out.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":45,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":42,"y":23.5}},"ball":"o1","actions":[{"type":"screen","from":"o5","to":"o1","path":[]}],"note":"5 comes up to screen on the top side."},{"ms":1000,"positions":{"o1":{"x":32,"y":20},"o2":{"x":48.5,"y":3},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":42,"y":23.5}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[{"x":41,"y":26.5}]}],"note":"1 goes over the screen toward the middle."},{"ms":1000,"positions":{"o1":{"x":32,"y":20},"o2":{"x":48.5,"y":3},"o3":{"x":25,"y":31},"o4":{"x":1.5,"y":3},"o5":{"x":28,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[]},{"type":"cut","from":"o3","path":[]}],"note":"5 rolls to the basket; 3 lifts to the top for the pass back out."},{"ms":1000,"positions":{"o1":{"x":32,"y":20},"o2":{"x":48.5,"y":3},"o3":{"x":25,"y":31},"o4":{"x":1.5,"y":3},"o5":{"x":28,"y":8}},"ball":"o5","actions":[{"type":"pass","from":"o1","to":"o5","path":[]}],"note":"Pass to 5, or to 3 at the top, or keep driving."}]}'::jsonb, false),
  ('pick-and-pop', 'Pick-and-pop', 'pick_and_roll', 'U12', ARRAY['ball screen', 'pop', 'shooter']::text[], '4 screens for 1, then steps back out to the top for a shot while 1 drives. Good for a screener who can shoot.', ARRAY['A pick-and-pop is a pick-and-roll where the screener steps out for a shot instead of rolling.', '4 sets the screen, then pops out behind the three-point line.', '1 drives hard so 4''s defender has to help, then passes back to 4.', '5 clears to the other side to keep the lane empty.', 'Use it when your screener can shoot.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":17,"y":19},"o5":{"x":15.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":21.5,"y":28.5},"o5":{"x":15.5,"y":8}},"ball":"o1","actions":[{"type":"screen","from":"o4","to":"o1","path":[]}],"note":"4 screens for 1."},{"ms":1000,"positions":{"o1":{"x":16,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":21.5,"y":28.5},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[{"x":18.5,"y":31}]},{"type":"cut","from":"o5","path":[]}],"note":"1 comes off the screen; 5 clears to the other block."},{"ms":1000,"positions":{"o1":{"x":16,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":25,"y":31},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o4","path":[]}],"note":"4 pops back out to the top instead of rolling."},{"ms":1000,"positions":{"o1":{"x":16,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":25,"y":31},"o5":{"x":34.5,"y":8}},"ball":"o4","actions":[{"type":"pass","from":"o1","to":"o4","path":[]}],"note":"4 catches ready to shoot."}]}'::jsonb, false),
  ('blob-stack', 'Stack: baseline out of bounds', 'blob', 'U10', ARRAY['out of bounds', 'stack', 'screens']::text[], 'Two stacks of two on the blocks, with the ball out under your own basket. A screen sends a shooter to the corner, then a cutter goes to the basket.', ARRAY['Line up in two stacks of two on the blocks. Your best passer takes it out.', 'The inbounder slaps the ball to start everyone at once.', '5 turns and screens; 3 pops to the corner ready to shoot.', '4 cuts to the basket while the defence watches the corner.', '2 is the safe pass at the top. Never throw a pass you are not sure of.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":14.5,"y":13},"o3":{"x":35.5,"y":13},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":35.5,"y":13},"o4":{"x":15.5,"y":8},"o5":{"x":37.5,"y":10}},"ball":"o1","actions":[{"type":"screen","from":"o5","to":"o3","path":[]},{"type":"cut","from":"o2","path":[]}],"note":"5 screens for 3; 2 goes out to the top as the safe pass."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":37.5,"y":10}},"ball":"o1","actions":[{"type":"cut","from":"o3","path":[{"x":40,"y":8}]}],"note":"3 pops off the screen to the corner."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":23,"y":6.5},"o5":{"x":37.5,"y":10}},"ball":"o1","actions":[{"type":"cut","from":"o4","path":[]}],"note":"4 cuts to the basket while the defence watches the corner."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":23,"y":6.5},"o5":{"x":37.5,"y":10}},"ball":"o4","actions":[{"type":"pass","from":"o1","to":"o4","path":[]}],"note":"Pass to 4 at the basket, 3 in the corner, or 2 at the top."}]}'::jsonb, true),
  ('blob-line', 'Line: baseline out of bounds', 'blob', 'U10', ARRAY['out of bounds', 'line', 'screens']::text[], 'Four players in a line across the free throw line. On the slap they all go: one to the corner, one to the top, and a screen frees 4 at the basket.', ARRAY['Line up across the free throw line, everyone facing the ball.', 'Everyone moves on the slap, at the same time.', '5 screens for 4 and holds still; 4 cuts to the basket with a hand up.', '2 goes to the ball-side corner; 3 goes out to the top as the safe pass.', 'After the screen, 5 pops to the high post as another target.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":44,"y":19},"o3":{"x":6,"y":19},"o4":{"x":17,"y":19},"o5":{"x":33,"y":19}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":48.5,"y":3},"o3":{"x":25,"y":31},"o4":{"x":17,"y":19},"o5":{"x":21,"y":16}},"ball":"o1","actions":[{"type":"cut","from":"o2","path":[{"x":46,"y":10}]},{"type":"cut","from":"o3","path":[]},{"type":"screen","from":"o5","to":"o4","path":[]}],"note":"2 goes to the corner, 3 to the top as the safe pass. 5 screens for 4."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":48.5,"y":3},"o3":{"x":25,"y":31},"o4":{"x":23.5,"y":7},"o5":{"x":21,"y":16}},"ball":"o1","actions":[{"type":"cut","from":"o4","path":[{"x":21,"y":12}]}],"note":"4 cuts off the screen to the basket."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":48.5,"y":3},"o3":{"x":25,"y":31},"o4":{"x":23.5,"y":7},"o5":{"x":25,"y":20}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[]}],"note":"5 pops back up to the high post."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":48.5,"y":3},"o3":{"x":25,"y":31},"o4":{"x":23.5,"y":7},"o5":{"x":25,"y":20}},"ball":"o4","actions":[{"type":"pass","from":"o1","to":"o4","path":[]}],"note":"Pass to 4 at the basket, 2 in the corner, or 5 at the high post."}]}'::jsonb, false),
  ('blob-screen-the-screener', 'Box: screen the screener', 'blob', 'U11', ARRAY['out of bounds', 'box', 'screen the screener']::text[], 'From a box under your own basket: 3 screens for 2, then 5 screens for 3. The defence watches the first cut, so the screener is often open at the basket.', ARRAY['Set up in a box. Two screens in a row: the first screener gets screened too.', '3 screens for 2, then waits for 5''s screen.', 'The defence watches 2 cut, so 3 is often open at the basket.', 'Every screener holds still with a wide base. No moving screens.', '4 pops to the corner, so there is room near the basket.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":17,"y":19},"o3":{"x":33,"y":19},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":17,"y":19},"o3":{"x":20.5,"y":17.5},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[{"type":"screen","from":"o3","to":"o2","path":[]}],"note":"3 screens across for 2."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":40,"y":3},"o3":{"x":20.5,"y":17.5},"o4":{"x":15.5,"y":8},"o5":{"x":22,"y":14}},"ball":"o1","actions":[{"type":"cut","from":"o2","path":[{"x":28,"y":11}]},{"type":"screen","from":"o5","to":"o3","path":[]}],"note":"2 cuts off the screen to the ball side. 5 screens for the screener, 3."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":40,"y":3},"o3":{"x":25.5,"y":7.5},"o4":{"x":1.5,"y":3},"o5":{"x":22,"y":14}},"ball":"o1","actions":[{"type":"cut","from":"o3","path":[{"x":23.5,"y":11}]},{"type":"cut","from":"o4","path":[]}],"note":"3 cuts off 5 to the basket; 4 pops to the corner."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":40,"y":3},"o3":{"x":25.5,"y":7.5},"o4":{"x":1.5,"y":3},"o5":{"x":22,"y":14}},"ball":"o3","actions":[{"type":"pass","from":"o1","to":"o3","path":[]}],"note":"Pass to 3 at the basket, or to 2 on the ball side."}]}'::jsonb, false),
  ('blob-inbounder-cut', 'Box: the inbounder cuts in', 'blob', 'U10', ARRAY['out of bounds', 'box', 'inbounder']::text[], 'Get the ball in to the corner, then screen for the player who passed it in. Defenders often forget the inbounder once the ball is in.', ARRAY['Once the ball is in, the inbounder is a player again. Defenders often forget them.', '3 pops out to the corner to catch the inbound pass.', '5 screens for 1 straight after the pass.', '1 steps in and cuts to the basket with a hand up.', '2 stays at the top as the safe pass if nothing is open.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":17,"y":19},"o3":{"x":33,"y":19},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o3","path":[{"x":40,"y":10}]},{"type":"cut","from":"o2","path":[]}],"note":"3 pops out to the corner; 2 goes out to the top."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o3","actions":[{"type":"pass","from":"o1","to":"o3","path":[]}],"note":"Inbound to 3 in the corner."},{"ms":1000,"positions":{"o1":{"x":31,"y":-2.5},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":33,"y":3}},"ball":"o3","actions":[{"type":"screen","from":"o5","to":"o1","path":[]}],"note":"5 screens for 1, who has just passed the ball in."},{"ms":1000,"positions":{"o1":{"x":26,"y":6},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":1.5,"y":3},"o5":{"x":33,"y":3}},"ball":"o3","actions":[{"type":"cut","from":"o1","path":[{"x":30,"y":1}]},{"type":"cut","from":"o4","path":[]}],"note":"1 steps in and cuts off 5 to the basket; 4 clears to the corner."},{"ms":1000,"positions":{"o1":{"x":26,"y":6},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":1.5,"y":3},"o5":{"x":33,"y":3}},"ball":"o1","actions":[{"type":"pass","from":"o3","to":"o1","path":[]}],"note":"Pass to 1 for the layup."}]}'::jsonb, false),
  ('slob-box', 'Box: sideline out of bounds', 'slob', 'U10', ARRAY['out of bounds', 'sideline', 'down screen']::text[], 'The ball is out on the sideline. 5 screens down for 1 to come and get it, then turns and goes to the basket.', ARRAY['Get the ball in safely first. Then run the play.', '5 screens for 1, then turns and goes to the basket.', '1 comes up hard to the wing to catch, then faces the basket.', '2 goes to the top as the safe pass.', 'The inbounder steps in to the corner after passing, so the floor stays spread.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":34.5,"y":8},"o2":{"x":17,"y":19},"o3":{"x":52.5,"y":26},"o4":{"x":15.5,"y":8},"o5":{"x":33,"y":19}},"ball":"o3","actions":[]},{"ms":1000,"positions":{"o1":{"x":34.5,"y":8},"o2":{"x":17,"y":19},"o3":{"x":52.5,"y":26},"o4":{"x":15.5,"y":8},"o5":{"x":35,"y":12.5}},"ball":"o3","actions":[{"type":"screen","from":"o5","to":"o1","path":[]}],"note":"5 goes down to screen for 1."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":25,"y":31},"o3":{"x":52.5,"y":26},"o4":{"x":15.5,"y":8},"o5":{"x":35,"y":12.5}},"ball":"o3","actions":[{"type":"cut","from":"o1","path":[{"x":38,"y":14}]},{"type":"cut","from":"o2","path":[]}],"note":"1 comes up off the screen to the wing; 2 goes out to the top."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":25,"y":31},"o3":{"x":52.5,"y":26},"o4":{"x":15.5,"y":8},"o5":{"x":35,"y":12.5}},"ball":"o1","actions":[{"type":"pass","from":"o3","to":"o1","path":[]}],"note":"Inbound to 1 on the wing."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":28,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[]},{"type":"cut","from":"o3","path":[{"x":49.5,"y":14}]}],"note":"5 turns and goes to the basket; 3 steps in to the corner."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":25,"y":31},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":28,"y":8}},"ball":"o5","actions":[{"type":"pass","from":"o1","to":"o5","path":[]}],"note":"Pass inside to 5, or to 3 in the corner."}]}'::jsonb, true),
  ('slob-stack', 'Stack: sideline out of bounds', 'slob', 'U10', ARRAY['out of bounds', 'sideline', 'stack']::text[], 'Three players stacked near the ball break three ways on the slap, then 4 steps down to the block once the defence has spread out.', ARRAY['Line up in a stack near the ball. Everyone breaks on the slap.', '1 goes to the wing, 5 to the corner, 2 to the top: three ways to get the ball in.', '4 waits, then steps down to the block once the defence has spread out.', 'Catch, face the basket, and look inside to 4.', 'Inbounder: after passing, step back onto the court for a pass back.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":34.5,"y":20},"o2":{"x":15.5,"y":28.5},"o3":{"x":52.5,"y":26},"o4":{"x":34.5,"y":16},"o5":{"x":34.5,"y":12}},"ball":"o3","actions":[]},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":25,"y":31},"o3":{"x":52.5,"y":26},"o4":{"x":34.5,"y":16},"o5":{"x":48.5,"y":3}},"ball":"o3","actions":[{"type":"cut","from":"o1","path":[]},{"type":"cut","from":"o5","path":[{"x":40,"y":8}]},{"type":"cut","from":"o2","path":[]}],"note":"1 breaks to the wing, 5 to the corner, 2 to the top."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":25,"y":31},"o3":{"x":52.5,"y":26},"o4":{"x":34.5,"y":8},"o5":{"x":48.5,"y":3}},"ball":"o3","actions":[{"type":"cut","from":"o4","path":[]}],"note":"4 steps down to the block."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":25,"y":31},"o3":{"x":52.5,"y":26},"o4":{"x":34.5,"y":8},"o5":{"x":48.5,"y":3}},"ball":"o1","actions":[{"type":"pass","from":"o3","to":"o1","path":[]}],"note":"Inbound to 1 on the wing."},{"ms":1000,"positions":{"o1":{"x":45,"y":21},"o2":{"x":25,"y":31},"o3":{"x":34.5,"y":28.5},"o4":{"x":34.5,"y":8},"o5":{"x":48.5,"y":3}},"ball":"o4","actions":[{"type":"pass","from":"o1","to":"o4","path":[]},{"type":"cut","from":"o3","path":[]}],"note":"Pass inside to 4. 3 steps in for a pass back."}]}'::jsonb, false),
  ('slob-back-screen', 'Sideline: screen for the inbounder', 'slob', 'U11', ARRAY['out of bounds', 'sideline', 'back screen']::text[], 'Get it in to 1, then 5 sets a back screen for the inbounder, who cuts to the basket. Defenders often relax once the ball is in.', ARRAY['Get the ball in to 1 first.', 'The inbounder steps onto the wing after passing. Defenders often relax here.', '5 sets the screen behind 3''s defender and holds still.', '3 cuts to the basket past the screener''s shoulder, hand up.', '4 lifts to the top so the ball can swing if 3 is covered.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":5,"y":21},"o3":{"x":52.5,"y":26},"o4":{"x":25,"y":20},"o5":{"x":33,"y":19}},"ball":"o3","actions":[]},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":5,"y":21},"o3":{"x":52.5,"y":26},"o4":{"x":25,"y":20},"o5":{"x":33,"y":19}},"ball":"o3","actions":[{"type":"cut","from":"o1","path":[]}],"note":"1 comes toward the ball."},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":5,"y":21},"o3":{"x":52.5,"y":26},"o4":{"x":25,"y":20},"o5":{"x":33,"y":19}},"ball":"o1","actions":[{"type":"pass","from":"o3","to":"o1","path":[]}]},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":5,"y":21},"o3":{"x":45,"y":21},"o4":{"x":25,"y":20},"o5":{"x":41,"y":17.5}},"ball":"o1","actions":[{"type":"cut","from":"o3","path":[]},{"type":"screen","from":"o5","to":"o3","path":[]}],"note":"3 steps in to the wing; 5 sets a back screen behind 3''s defender."},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":5,"y":21},"o3":{"x":28,"y":7.5},"o4":{"x":25,"y":31},"o5":{"x":41,"y":17.5}},"ball":"o1","actions":[{"type":"cut","from":"o3","path":[{"x":39,"y":13}]},{"type":"cut","from":"o4","path":[]}],"note":"3 cuts to the basket off the screen; 4 lifts to the top."},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":5,"y":21},"o3":{"x":28,"y":7.5},"o4":{"x":25,"y":31},"o5":{"x":41,"y":17.5}},"ball":"o3","actions":[{"type":"pass","from":"o1","to":"o3","path":[]}],"note":"Bounce pass to 3. If 3 is covered, swing it to 4 at the top."}]}'::jsonb, false),
  ('slob-ball-screen', 'Sideline: get it in, then pick-and-roll', 'slob', 'U12', ARRAY['out of bounds', 'sideline', 'ball screen']::text[], '1 cuts out to catch the inbound pass, and 5 runs up for a pick-and-roll straight away, before the defence is set.', ARRAY['Get it in first: 1 cuts hard out to the ball.', '5 runs up and screens as soon as 1 catches.', '1 waits for the screen, then attacks the middle.', '5 rolls to the basket with a hand up.', '2 steps in to the corner after the pass. A defender who helps leaves 2 open.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":20},"o2":{"x":52.5,"y":30},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":34.5,"y":8}},"ball":"o2","actions":[]},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":52.5,"y":30},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":34.5,"y":8}},"ball":"o2","actions":[{"type":"cut","from":"o1","path":[{"x":30,"y":23}]}],"note":"1 cuts out to the ball."},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":52.5,"y":30},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[{"type":"pass","from":"o2","to":"o1","path":[]}]},{"ms":1000,"positions":{"o1":{"x":34.5,"y":28.5},"o2":{"x":48.5,"y":3},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":31.5,"y":27}},"ball":"o1","actions":[{"type":"screen","from":"o5","to":"o1","path":[]},{"type":"cut","from":"o2","path":[{"x":49.5,"y":16}]}],"note":"5 runs up to screen for 1; 2 steps in to the corner."},{"ms":1000,"positions":{"o1":{"x":25,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":31.5,"y":27}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[{"x":31,"y":30.5}]}],"note":"1 comes off the screen toward the middle."},{"ms":1000,"positions":{"o1":{"x":25,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":15.5,"y":28.5},"o4":{"x":1.5,"y":3},"o5":{"x":27,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[]},{"type":"cut","from":"o3","path":[]}],"note":"5 rolls to the basket; 3 lifts for the pass back out."},{"ms":1000,"positions":{"o1":{"x":25,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":15.5,"y":28.5},"o4":{"x":1.5,"y":3},"o5":{"x":27,"y":8}},"ball":"o5","actions":[{"type":"pass","from":"o1","to":"o5","path":[]}],"note":"Pass to 5 rolling, or to 2 in the corner."}]}'::jsonb, false),
  ('press-break-reverse', 'Press break: swing it back', 'press_break', 'U12', ARRAY['press break', 'full court', 'reversal']::text[], 'When the press traps the first pass, swing the ball back to the inbounder and up the other side. The hoop in the picture is the one you defend.', ARRAY['The inbounder steps in after the pass, behind the ball, ready for a pass back.', 'In a trap, do not panic: pivot, keep the ball high, and look for the pass back.', 'Swing the ball away from the trap. The press cannot cover both sides.', 'Pass ahead whenever you can. A pass beats the press faster than a dribble.', 'Someone is always ahead of the ball, so there is a pass up the floor.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":15,"y":12},"o2":{"x":35,"y":12},"o3":{"x":44,"y":40},"o4":{"x":20,"y":-2.5},"o5":{"x":25,"y":30}},"ball":"o4","actions":[]},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":35,"y":12},"o3":{"x":44,"y":40},"o4":{"x":20,"y":-2.5},"o5":{"x":25,"y":30}},"ball":"o4","actions":[{"type":"cut","from":"o1","path":[]}],"note":"1 cuts out to the free throw line extended."},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":35,"y":12},"o3":{"x":44,"y":40},"o4":{"x":20,"y":-2.5},"o5":{"x":25,"y":30}},"ball":"o1","actions":[{"type":"pass","from":"o4","to":"o1","path":[]}],"note":"Inbound to 1."},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":45,"y":21},"o3":{"x":44,"y":40},"o4":{"x":20,"y":2},"o5":{"x":25,"y":20}},"ball":"o1","actions":[{"type":"cut","from":"o4","path":[]},{"type":"cut","from":"o2","path":[]},{"type":"cut","from":"o5","path":[]}],"note":"The press traps 1. 4 steps in behind the ball; 2 gets open on the far side; 5 comes back to the middle."},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":45,"y":21},"o3":{"x":44,"y":40},"o4":{"x":20,"y":2},"o5":{"x":25,"y":20}},"ball":"o4","actions":[{"type":"pass","from":"o1","to":"o4","path":[]}],"note":"Pass back to 4, away from the trap."},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":45,"y":21},"o3":{"x":30,"y":49},"o4":{"x":20,"y":2},"o5":{"x":25,"y":20}},"ball":"o2","actions":[{"type":"pass","from":"o4","to":"o2","path":[]},{"type":"cut","from":"o3","path":[]}],"note":"4 swings it up to 2. 3 runs ahead past half court."},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":40,"y":46},"o3":{"x":30,"y":49},"o4":{"x":20,"y":2},"o5":{"x":27,"y":38}},"ball":"o2","actions":[{"type":"dribble","from":"o2","path":[]},{"type":"cut","from":"o5","path":[]}],"note":"2 dribbles over half court; 5 follows in the middle."}]}'::jsonb, false),
  ('zone-2-3-high-post', 'vs 2-3 zone: high post and short corner', 'zone_offence', 'U15', ARRAY['2-3 zone', 'high post', 'short corner']::text[], 'Beat a 2-3 zone through the middle. 5 flashes to the high post, passes to 4 in the short corner behind the zone, then dives to the basket.', ARRAY['Against a 2-3 zone, start with one player at the top: it splits the two front defenders.', 'Get the ball to the high post. The zone has to squeeze in to guard it.', '5 catches, turns and faces the basket before deciding.', 'The short corner is behind the zone. When the middle defender steps up, 4 is open there.', 'Zones are only allowed from U15 in Basketball Ireland underage games.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":34.5,"y":8},"o5":{"x":15.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":40,"y":3},"o5":{"x":25,"y":20}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[]},{"type":"cut","from":"o4","path":[]}],"note":"5 flashes to the middle of the zone; 4 slides to the short corner."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":40,"y":3},"o5":{"x":25,"y":20}},"ball":"o5","actions":[{"type":"pass","from":"o1","to":"o5","path":[]},{"type":"cut","from":"o3","path":[]}],"note":"5 catches facing the basket. 3 drops to the corner."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":40,"y":3},"o5":{"x":25,"y":20}},"ball":"o4","actions":[{"type":"pass","from":"o5","to":"o4","path":[]}],"note":"The middle defender steps up to 5, so 4 is open in the short corner."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":40,"y":3},"o5":{"x":26,"y":7}},"ball":"o4","actions":[{"type":"cut","from":"o5","path":[]}],"note":"5 dives to the basket behind the defence."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":1.5,"y":3},"o4":{"x":40,"y":3},"o5":{"x":26,"y":7}},"ball":"o5","actions":[{"type":"pass","from":"o4","to":"o5","path":[]}],"note":"Shoot, or pass to 5 at the basket."}]}'::jsonb, false),
  ('zone-2-3-overload', 'vs 2-3 zone: overload one side', 'zone_offence', 'U15', ARRAY['2-3 zone', 'overload', 'baseline cut']::text[], 'Put more attackers on one side than the zone can guard. 3 runs the baseline to the far corner, and a pass there pulls a defender out and opens the block.', ARRAY['Overload: put more attackers on one side than the zone has defenders there.', '3 runs the baseline to make the overload. Go fast, behind the defence.', 'A pass to the corner pulls the back defender out, which opens the block.', 'Fake before you pass: zone defenders follow your eyes.', '4 slides to the far side for a rebound or a pass across.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":25,"y":20},"o5":{"x":15.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":48.5,"y":3},"o4":{"x":25,"y":20},"o5":{"x":15.5,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o3","path":[{"x":18,"y":3},{"x":34,"y":2}]}],"note":"3 runs along the baseline to the right corner."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":48.5,"y":3},"o4":{"x":25,"y":20},"o5":{"x":34.5,"y":8}},"ball":"o2","actions":[{"type":"pass","from":"o1","to":"o2","path":[]},{"type":"cut","from":"o5","path":[]}],"note":"5 follows to the ball side: now three players are on the right."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o3","actions":[{"type":"pass","from":"o2","to":"o3","path":[]},{"type":"cut","from":"o4","path":[]}],"note":"The corner pass pulls a back defender out. 4 slides to the far side."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":48.5,"y":3},"o4":{"x":15.5,"y":8},"o5":{"x":34.5,"y":8}},"ball":"o5","actions":[{"type":"pass","from":"o3","to":"o5","path":[]}],"note":"5 is open on the block the defender left. If the zone covers 5, pass back out."}]}'::jsonb, false),
  ('zone-3-2-gaps', 'vs 3-2 zone: two at the top', 'zone_offence', 'U15', ARRAY['3-2 zone', 'gaps', 'high post']::text[], 'Against a zone with three defenders at the top, start with two guards in the gaps. A pass to the corner makes a back defender run out, and 5 dives in behind them.', ARRAY['Against three at the top, start with two guards, each standing in a gap.', 'In a gap, two defenders have to decide who guards you.', 'The corners are hard for a 3-2 to cover. A pass there makes the back defenders run.', '5 flashes to the middle, then dives to the block the defender left.', 'Move after every pass. A zone is easier to beat when it has to keep shifting.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":15.5,"y":28.5},"o2":{"x":34.5,"y":28.5},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":15.5,"y":28.5},"o2":{"x":34.5,"y":28.5},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":25,"y":20}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[]}],"note":"5 flashes into the middle, behind the top three defenders."},{"ms":1000,"positions":{"o1":{"x":15.5,"y":28.5},"o2":{"x":34.5,"y":28.5},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":25,"y":20}},"ball":"o3","actions":[{"type":"pass","from":"o1","to":"o3","path":[]}],"note":"Pass to the corner: a back defender has to run out."},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":25,"y":31},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o3","actions":[{"type":"cut","from":"o5","path":[]},{"type":"cut","from":"o1","path":[]},{"type":"cut","from":"o2","path":[]}],"note":"5 dives to the block that defender left. 1 slides to the wing; 2 slides to the top."},{"ms":1000,"positions":{"o1":{"x":5,"y":21},"o2":{"x":25,"y":31},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o5","actions":[{"type":"pass","from":"o3","to":"o5","path":[]}],"note":"Pass inside to 5, or back out to 1 for a shot."}]}'::jsonb, false),
  ('zone-1-3-1-corners', 'vs 1-3-1 zone: use the corners', 'zone_offence', 'U15', ARRAY['1-3-1 zone', 'corners', 'baseline']::text[], 'A 1-3-1 zone has one defender along the baseline, so fill both corners. A pass to one corner pulls that defender out, and 5 slides in behind.', ARRAY['The 1-3-1 has only one defender along the baseline. The corners are its weak spot.', 'Start with two at the top, in the gaps beside the top defender.', 'Fill both corners. The back defender cannot guard both.', 'After a corner pass, 5 slides to the block behind the defence.', 'Look for the pass across to the far corner too.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":15.5,"y":28.5},"o2":{"x":34.5,"y":28.5},"o3":{"x":5,"y":21},"o4":{"x":45,"y":21},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":15.5,"y":28.5},"o2":{"x":34.5,"y":28.5},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o3","path":[]},{"type":"cut","from":"o4","path":[]}],"note":"3 and 4 drop to the corners, where the 1-3-1 is weakest."},{"ms":1000,"positions":{"o1":{"x":15.5,"y":28.5},"o2":{"x":34.5,"y":28.5},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":34.5,"y":8}},"ball":"o3","actions":[{"type":"pass","from":"o1","to":"o3","path":[]}],"note":"Pass to the corner: the one back defender has to run out."},{"ms":1000,"positions":{"o1":{"x":15.5,"y":28.5},"o2":{"x":34.5,"y":28.5},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o3","actions":[{"type":"cut","from":"o5","path":[{"x":25,"y":6}]}],"note":"5 slides to the ball-side block behind the defence."},{"ms":1000,"positions":{"o1":{"x":15.5,"y":28.5},"o2":{"x":34.5,"y":28.5},"o3":{"x":1.5,"y":3},"o4":{"x":48.5,"y":3},"o5":{"x":15.5,"y":8}},"ball":"o5","actions":[{"type":"pass","from":"o3","to":"o5","path":[]}],"note":"Pass inside to 5. If the zone sinks, swing it back out to 1."}]}'::jsonb, false),
  ('last-shot-spread', 'Last shot: spread the floor and drive', 'end_of_quarter', 'U10', ARRAY['end of quarter', 'last shot', 'driving']::text[], 'For the last attack of a quarter, when less time is left on the game clock than the shot clock. Everyone clears out and 1 drives with about 7 seconds to go.', ARRAY['Hold the ball near half court until it is time to go. Do not let the clock run out.', 'Start with about 7 seconds left: enough time to score, too little for the other team to reply.', 'Everyone else spreads out, so 1 has room to drive.', 'If a defender helps, pass to the player they left.', 'Everyone crashes for the rebound once the shot goes up.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":38},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":25,"y":20},"o5":{"x":34.5,"y":8}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":38},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":48.5,"y":3}},"ball":"o1","actions":[{"type":"cut","from":"o4","path":[{"x":12,"y":8}]},{"type":"cut","from":"o5","path":[]}],"note":"With about 10 seconds left, the bigs clear to the corners."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":48.5,"y":3}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[]}],"note":"At about 7 seconds, 1 starts."},{"ms":1000,"positions":{"o1":{"x":21.5,"y":12},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":48.5,"y":3}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[]}],"note":"1 drives hard to the basket."},{"ms":1000,"positions":{"o1":{"x":21.5,"y":12},"o2":{"x":45,"y":21},"o3":{"x":5,"y":21},"o4":{"x":1.5,"y":3},"o5":{"x":48.5,"y":3}},"ball":"o3","actions":[{"type":"pass","from":"o1","to":"o3","path":[]}],"note":"If 3''s defender helps, pass to 3 for the shot. If nobody helps, 1 finishes."}]}'::jsonb, true),
  ('last-shot-ball-screen', 'Last shot: high ball screen', 'end_of_quarter', 'U12', ARRAY['end of quarter', 'last shot', 'ball screen']::text[], 'For the last attack of a quarter: 1 waits near half court, then 5 sets a ball screen at the top with about 8 seconds left.', ARRAY['Start with about 8 seconds left. A pick-and-roll takes a little longer than a drive.', '5 screens at the top and holds still; 1 waits for it.', '1 attacks: shoot, pass to 5 rolling, or pass to the open corner.', 'Get the shot up before the buzzer. A good shot with 2 seconds left beats a rushed one at the end.', 'Everyone crashes for the rebound.']::text[], '{"v":1,"court":"half","players":[{"id":"o1","side":"offence","label":"1"},{"id":"o2","side":"offence","label":"2"},{"id":"o3","side":"offence","label":"3"},{"id":"o4","side":"offence","label":"4"},{"id":"o5","side":"offence","label":"5"}],"frames":[{"ms":0,"positions":{"o1":{"x":25,"y":38},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":5,"y":21},"o5":{"x":25,"y":20}},"ball":"o1","actions":[]},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":5,"y":21},"o5":{"x":25,"y":20}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[]}],"note":"At about 8 seconds, 1 dribbles to the top."},{"ms":1000,"positions":{"o1":{"x":25,"y":31},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":5,"y":21},"o5":{"x":28,"y":28.5}},"ball":"o1","actions":[{"type":"screen","from":"o5","to":"o1","path":[]}],"note":"5 runs up to screen."},{"ms":1000,"positions":{"o1":{"x":36,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":28,"y":28.5}},"ball":"o1","actions":[{"type":"dribble","from":"o1","path":[{"x":31.5,"y":30.5}]},{"type":"cut","from":"o4","path":[]}],"note":"1 comes off the screen; 4 lifts behind the play as the safe pass."},{"ms":1000,"positions":{"o1":{"x":36,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":27,"y":8}},"ball":"o1","actions":[{"type":"cut","from":"o5","path":[]}],"note":"5 rolls to the basket."},{"ms":1000,"positions":{"o1":{"x":36,"y":21},"o2":{"x":48.5,"y":3},"o3":{"x":1.5,"y":3},"o4":{"x":15.5,"y":28.5},"o5":{"x":27,"y":8}},"ball":"o5","actions":[{"type":"pass","from":"o1","to":"o5","path":[]}],"note":"Pass to 5, shoot, or pass to 2 in the corner if their defender helps."}]}'::jsonb, false)
